#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Prove ranges_no_overlap invariant
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // The only change in the transition is that node_id's combiner state changes from 
        // Reading(Range{start, end, cur}) to Reading(Guard{start, end, cur, val})
        // This doesn't affect the no_overlap_with relation because:
        // 1. For i != node_id and j != node_id, combiner states are unchanged
        // 2. For combinations involving node_id, we need to check that the Guard state still satisfies no_overlap

        if i == node_id || j == node_id {
            // We only need to check combinations involving the modified node
            // The transition only affects overlap checks between Appending states and Reading(Guard) states
            // According to no_overlap_with definition, CombinerState::Appending only has special handling
            // for CombinerState::Reading(ReaderState::Guard), all other cases return true

            // Since the only change is from Range to Guard for node_id, and Guard is still a Reading state,
            // the overlap relationships should be preserved
        }

        // For all other pairs, the relationship is unchanged from pre to post
        assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
    }

    // Prove all_reader_state_valid invariant
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {
        if nid == node_id {
            // This is the node we modified - it went from Range to Guard
            match post.combiner[nid].get_Reading_0() {
                ReaderState::Guard { start, end, cur, val } => {
                    // Check all conditions for Guard state validity:
                    assert(post.local_versions[nid] == start); // Unchanged from pre
                    assert(start <= end); // Unchanged from pre
                    assert((post.tail as int) - (post.buffer_size as int) <= end <= (post.tail as int)); // Unchanged from pre
                    assert(start <= cur < end); // cur < end is required by transition

                    // For the alive bits condition:
                    assert forall |i| start <= i <= cur implies log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
                        if i == cur {
                            // This is the key one - we specifically required this in the transition
                            // The transition has: have alive_bits >= [ log_entry_idx(cur as int, pre.buffer_size) => log_entry_alive_value(cur as int, pre.buffer_size) ];
                            assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));
                        } else {
                            // For i < cur, this was true in pre and should still be true
                            // The transition doesn't modify alive_bits for i < cur
                            assert(log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
                            assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size));
                        }
                    };

                    // For the contents condition:
                    assert forall |i| start <= i <= cur implies post.contents.contains_key(i) by {
                        if i == cur {
                            // This is specifically what we added with birds_eye
                            // The transition has: birds_eye let val = pre.contents.index(cur as int);
                            assert(post.contents.contains_key(cur as int));
                        } else {
                            // For i < cur, this was true in pre and should still be true
                            // The transition doesn't modify contents for i < cur
                            assert(pre.contents.contains_key(i));
                            assert(post.contents.contains_key(i));
                        }
                    };

                    // Check the final conditions for Guard:
                    assert(post.contents.contains_key(cur as int));
                    assert(post.contents[cur as int] === val);
                },
                _ => { }
            }
        } else {
            // For other nodes, the reader state is unchanged
            assert(pre.combiner.contains_key(nid));
            assert(pre.combiner[nid] === post.combiner[nid]);
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            // Since the state is unchanged, validity is preserved
            assert(post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()));
        }
    }
}

