    // Prove ranges_no_overlap invariant
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // Since only node_id's combiner state changed, and it remained a Reading state
        // (just changing from Range to Guard), and no_overlap_with treats Reading(Range) and 
        // Reading(Guard) identically when checking against Appending states, the invariant is preserved.
        //
        // Specifically, no_overlap_with(CombinerState::Appending{cur_idx, tail}, CombinerState::Reading(ReaderState::Range{...}))
        // and no_overlap_with(CombinerState::Appending{cur_idx, tail}, CombinerState::Reading(ReaderState::Guard{...}))
        // both check the same condition: (cur_idx > cur) || (tail <= cur)
    }

    // Prove all_reader_state_valid invariant
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {
        if nid == node_id {
            // This is the node we modified - it went from Range to Guard
            match post.combiner[nid].get_Reading_0() {
                ReaderState::Guard { start, end, cur, val } => {
                    // Verify all conditions for Guard state validity:
                    // 1. start == local_versions[nid] (unchanged from pre)
                    assert(post.local_versions[nid] == start);

                    // 2. start <= end (unchanged from pre)
                    assert(start <= end);

                    // 3. bounds on end (unchanged from pre)
                    assert((post.tail as int) - (post.buffer_size as int) <= end <= (post.tail as int));

                    // 4. bounds on cur (cur < end is required by transition)
                    assert(start <= cur < end);

                    // 5. Alive bits condition: forall i in [start, cur], log_entry_is_alive holds
                    // For i == cur: required by transition
                    assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));

                    // For i < cur: was true in pre and unchanged in post
                    assert forall |i| start <= i < cur implies log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
                        assert(log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
                        // alive_bits is unchanged for indices < cur
                    };

                    // Combined:
                    assert forall |i| start <= i <= cur implies log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
                        if i == cur {
                            assert(log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size));
                        } else {
                            assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size));
                        }
                    };

                    // 6. Contents condition: forall i in [start, cur], contents.contains_key(i)
                    // For i == cur: pre.contents.contains_key(cur as int) by definition of index operation
                    // and post.contents.contains_key(cur as int) since contents is unchanged
                    assert(pre.contents.contains_key(cur as int));
                    assert(post.contents.contains_key(cur as int));
                    assert(post.contents[cur as int] === val); // val is defined as pre.contents.index(cur as int)

                    // For i < cur: was true in pre and unchanged in post
                    assert forall |i| start <= i < cur implies post.contents.contains_key(i) by {
                        assert(pre.contents.contains_key(i));
                    };

                    // Combined:
                    assert forall |i| start <= i <= cur implies post.contents.contains_key(i) by {
                        if i == cur {
                            assert(post.contents.contains_key(cur as int));
                        } else {
                            assert(post.contents.contains_key(i));
                        }
                    };

                    // Final conditions for Guard:
                    assert(post.contents.contains_key(cur as int));
                    assert(post.contents[cur as int] === val);
                },
                _ => { }
            }
        } else {
            // For other nodes, the reader state is unchanged
            assert(post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()));
        }
    }
}

