#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Prove ranges_no_overlap invariant
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // Assume pre satisfies ranges_no_overlap
        assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));

        // The only change in transition is:
        // - Remove: node_id => CombinerState::Reading(ReaderState::Range{ start, end, cur })
        // - Add:    node_id => CombinerState::Reading(ReaderState::Guard{ start, end, cur, val })
        //
        // Case analysis:
        // 1. If i != node_id and j != node_id: post.combiner[i] == pre.combiner[i] and post.combiner[j] == pre.combiner[j]
        //    Therefore post.combiner[i].no_overlap_with(post.combiner[j]) == pre.combiner[i].no_overlap_with(pre.combiner[j]) which is true
        //
        // 2. If i == node_id or j == node_id: Need to check combinations with node_id's new Guard state
        //    The no_overlap_with function checks:
        //    - CombinerState::Appending vs CombinerState::Reading(ReaderState::Guard): (cur_idx > cur) || (tail <= cur)
        //    - CombinerState::Appending vs CombinerState::Appending: (cur_idx >= tail2) || (tail <= cur_idx2)
        //    - All others: true
        //
        //    Since we only changed from Reading(Range) to Reading(Guard), and both have the same 'cur' value,
        //    the overlap conditions are identical.
        if i != node_id && j != node_id {
            assert(post.combiner[i] === pre.combiner[i]);
            assert(post.combiner[j] === pre.combiner[j]);
            assert(post.combiner[i].no_overlap_with(post.combiner[j]) === pre.combiner[i].no_overlap_with(pre.combiner[j]));
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        } else {
            // One of them is node_id, which changed from Range to Guard
            // Since both Range and Guard have the same start, end, cur values, 
            // and no_overlap_with depends only on these values for Reading states,
            // the result is the same.
        }
    }

    // Prove all_reader_state_valid invariant
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {
        if nid == node_id {
            // Show that the Guard state is valid
            match post.combiner[nid].get_Reading_0() {
                ReaderState::Guard { start, end, cur, val } => {
                    // Use the fact that pre.reader_state_valid(node_id, ReaderState::Range{start, end, cur}) holds
                    // and that the transition preserves start, end, cur values and adds appropriate constraints.
                    //
                    // The reader_state_valid conditions for Guard are:
                    // &&& self.local_versions[node_id] == start
                    // &&& start <= end  
                    // &&& (self.tail as int) - (self.buffer_size as int) <= end <= (self.tail as int)
                    // &&& start <= cur < end
                    // &&& (forall |i| start <= i <= cur ==> log_entry_is_alive(self.alive_bits, i, self.buffer_size))
                    // &&& (forall |i| start <= i <= cur ==> self.contents.contains_key(i))
                    // &&& self.contents.contains_key(cur as int)
                    // &&& self.contents[cur as int] === val
                    //
                    // Since these were true for the Range state (with <= cur replaced by < cur for some conditions)
                    // and the transition adds the missing requirements, they should all hold.
                },
                _ => { }
            }
        } else {
            // Other nodes unchanged
            assert(pre.combiner.contains_key(nid));
            assert(pre.combiner[nid] === post.combiner[nid]);
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()));
        }
    }
}

