fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Prove ranges_no_overlap invariant
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // Since pre satisfies the invariant and the transition is valid, post should also satisfy it.
        // The transition only modifies node_id's combiner state from Reading(Range) to Reading(Guard).
        // This change doesn't affect the no_overlap_with relationship because:
        // 1. For i != node_id and j != node_id: states are unchanged, so no_overlap_with is unchanged
        // 2. For cases involving node_id: 
        //    - no_overlap_with(Other, Reading(Range{..., cur})) and  
        //      no_overlap_with(Other, Reading(Guard{..., cur})) compute the same result since 'cur' is unchanged
    }

    // Prove all_reader_state_valid invariant
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {
        // The transition is valid, so post should satisfy the invariant.
        // We need to show that node_id's new Guard state is valid.
    }
}

