#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Prove ranges_no_overlap invariant
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // The transition only changes node_id's state from Reading(Range) to Reading(Guard)
        // All other combiner states remain the same.
        if i != node_id && j != node_id {
            // Both i and j are unchanged, so their no_overlap_with relationship is unchanged
            assert(post.combiner[i].no_overlap_with(post.combiner[j]) == pre.combiner[i].no_overlap_with(pre.combiner[j]));
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j])); // Pre satisfies invariant
        } else {
            // One of i,j is node_id. WLOG, assume i == node_id.
            // We need to show post.combiner[node_id].no_overlap_with(post.combiner[j]) holds.
            // 
            // The no_overlap_with function only has special handling when one state is Appending:
            // - Appending vs Reading(Guard): Check using 'cur' value
            // - Appending vs Appending: Check using indices
            // - All other combinations: Return true
            //
            // Since we only changed from Reading(Range) to Reading(Guard), and both have
            // the same 'cur' value, the overlap computation is identical.
            // Therefore post.combiner[node_id].no_overlap_with(post.combiner[j]) == pre.combiner[node_id].no_overlap_with(pre.combiner[j])
            // which is true since pre satisfies the invariant.
        }
    }

    // Prove all_reader_state_valid invariant
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {
        if nid != node_id {
            // Unchanged from pre, and pre satisfied the invariant
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.combiner[nid].get_Reading_0() === pre.combiner[nid].get_Reading_0());
        } else {
            // Need to show that the Guard state is valid
            // Since pre satisfied reader_state_valid for the Range state, and the transition
            // preserves all the required properties while strengthening some (adding equality for cur),
            // the Guard state should also be valid.
            match post.combiner[node_id].get_Reading_0() {
                ReaderState::Guard { start, end, cur, val } => {
                    // All the conditions that held for Range{start, end, cur} should still hold for Guard{start, end, cur, val}
                    // with minor adjustments to the bounds (<= cur instead of < cur for some conditions)
                },
                _ => { }
            }
        }
    }
}

