#[inductive(reader_guard)]
fn reader_guard_inductive(pre: Self, post: Self, node_id: NodeId) {
    // The transition changes node_id's combiner from Reading(Range) to Reading(Guard)
    // We need to show that both invariants still hold in post.

    // Prove ranges_no_overlap invariant
    assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
        post.combiner[i].no_overlap_with(post.combiner[j]) by {
        // Case 1: Neither i nor j is node_id
        if i != node_id && j != node_id {
            // States are unchanged, so no_overlap_with result is unchanged
            assert(post.combiner[i] === pre.combiner[i]);
            assert(post.combiner[j] === pre.combiner[j]);
            assert(post.combiner[i].no_overlap_with(post.combiner[j]) == pre.combiner[i].no_overlap_with(pre.combiner[j]));
            // Pre satisfied the invariant
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
        } else {
            // Case 2: One of i,j is node_id. Without loss of generality, assume i == node_id.
            // We're changing combiner[node_id] from Reading(Range{start,end,cur}) to Reading(Guard{start,end,cur,val})
            // The no_overlap_with function:
            // - Returns true for most combinations
            // - For Appending vs Reading(Guard), checks (cur_idx > cur) || (tail <= cur)  
            // - For Appending vs Appending, checks (cur_idx >= tail2) || (tail <= cur_idx2)
            //
            // Since we preserve start, end, and cur values, and no_overlap_with depends only on these
            // values for Reading states, the result is the same as in pre.
            assert(pre.combiner[i].no_overlap_with(pre.combiner[j])); // Pre satisfied invariant
        }
    }

    // Prove all_reader_state_valid invariant
    assert forall |nid| #[trigger] post.combiner.contains_key(nid) && post.combiner[nid].is_Reading() implies
        post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()) by {
        if nid != node_id {
            // State unchanged from pre, which satisfied the invariant
            assert(pre.combiner.contains_key(nid));
            assert(pre.combiner[nid] === post.combiner[nid]);
            assert(pre.reader_state_valid(nid, pre.combiner[nid].get_Reading_0()));
            assert(post.reader_state_valid(nid, post.combiner[nid].get_Reading_0()));
        } else {
            // Show that Guard state is valid
            // Pre had a valid Range state, and the transition adds the necessary conditions for Guard
            match post.combiner[node_id].get_Reading_0() {
                ReaderState::Guard { start, end, cur, val } => {
                    // Transition guarantees:
                    // 1. cur < end (explicitly required)
                    // 2. log_entry_is_alive(post.alive_bits, cur as int, post.buffer_size) (via have clause)
                    // 3. val = pre.contents.index(cur as int), so post.contents.contains_key(cur as int) and post.contents[cur as int] === val
                    // 4. start, end, cur values are preserved from the Range state
                    //
                    // Since pre.reader_state_valid(node_id, ReaderState::Range{start, end, cur}) held,
                    // and the Guard conditions are similar but with <= cur instead of < cur for some bounds,
                    // and we have the additional guarantees from the transition, the Guard state is valid.
                },
                _ => { }
            }
        }
    }
}

