                    //    For i < cur: true in pre, unchanged in post
                    //    For i == cur: ensured by transition
                    // &&& (forall |i| start <= i <= cur ==> self.contents.contains_key(i))
                    //    For i < cur: true in pre, unchanged in post  
                    //    For i == cur: pre.contents.contains_key(cur as int), preserved in post
                    // &&& self.contents.contains_key(cur as int)  // Follows from above
                    assert(post.contents.contains_key(cur as int));
                    // &&& self.contents[cur as int] === val  // Definition of val
                    assert(post.contents[cur as int] === val);
                },
                _ => { }
            }
        }
    }
}

